<script>let {data,form}=$props();</script><main><h1>Administration</h1>{#if form?.error}<p class="error">{form.error}</p>{/if}{#if !data.admin}<div class="panel"><form method="POST" action="?/login"><label>Mot de passe administrateur<input name="password" type="password" required /></label><button>Se connecter</button></form></div>{:else}<form method="POST" action="?/logout"><button class="secondary">Se déconnecter</button></form><div class="panel"><h2>Paramètres</h2><form method="POST" action="?/settings"><label><input type="checkbox" name="enabled" checked={data.enabled}/> Autoriser les nouveaux dépôts</label><label><input type="checkbox" name="approval" checked={data.approval}/> Valider les projets avant publication</label><button>Enregistrer</button></form></div><h2>Projets ({data.projects.length})</h2><div class="grid">{#each data.projects as p}<article class="panel"><h3>{p.title}</h3><p>{p.first_name} · {p.approved?'Publié':'En attente de validation'}</p><a href={'/project/'+p.id}>Aperçu</a><form method="POST" action="?/edit"><input type="hidden" name="id" value={p.id}/><label>Prénom<input name="first_name" value={p.first_name} required /></label><label>Titre<input name="title" value={p.title} required /></label><label>Description<textarea name="description" rows="3" required>{p.description}</textarea></label><button class="secondary">Enregistrer les modifications</button></form><div class="actions">{#if !p.approved}<form method="POST" action="?/approve"><input type="hidden" name="id" value={p.id}/><button>Valider</button></form>{/if}<form method="POST" action="?/delete" onsubmit={(e)=>{if(!confirm('Supprimer définitivement ce projet ?'))e.preventDefault()}}><input type="hidden" name="id" value={p.id}/><button class="danger">Supprimer</button></form></div></article>{/each}</div>{/if}</main>